//! SPP/MRP (SigProp/MagRef refinement) decode regression test.
//!
//! HT code-blocks with `num_passes > 1` carry SigProp and MagRef refinement passes after the
//! cleanup pass. This path was historically untested (Kakadu/OpenJPH reversible encoders emit
//! cleanup-only blocks), which hid a bug in the SIMD (AVX2/SSSE3) decoders' `rearrange_sigma`
//! (it zeroed each sigma row right after writing it) — the scalar path was correct, so the bug
//! only surfaced on the SIMD path the runtime actually selects. This test exercises refinement on
//! whatever decoder the host CPU dispatches to, so the regression can never return silently.
//!
//! Fixtures (regenerated by the dev harness; point `MLDIR` at the directory holding them). Lossy
//! HTJ2K is the only readily-available source of refinement passes:
//!   kdu_compress -i test.pgm -o spp_lossy1.j2c    Cmodes=HT Clayers=1 -rate 0.5
//!   kdu_compress -i test.pgm -o spp_lossy_ml.j2c  Cmodes=HT Clayers=4 -rate 0.2,0.5,1.0,2.0
//!   kdu_expand   -i spp_lossy1.j2c   -o spp_lossy1_ref.pgm
//!   kdu_expand   -i spp_lossy_ml.j2c -o spp_lossy_ml_ref.pgm
//! The test passes trivially when `MLDIR` (or a fixture) is absent, so CI without it stays green.

use std::path::PathBuf;
mod common;

/// Parse a binary P5 PGM into its raw samples (8-bit).
fn load_pgm(path: &PathBuf) -> Vec<i32> {
    common::pgm(path).2
}


#[test]
#[ignore = "needs external conformance fixtures (env vars): run with --ignored"]
fn spp_mrp_decode_matches_kakadu_within_tolerance() {
    let Ok(dir) = std::env::var("MLDIR") else {
        panic!("MLDIR unset — skipping SPP/MRP refinement validation");
    };
    let dir = PathBuf::from(dir);
    let mut checked = 0;
    for stem in ["spp_lossy1", "spp_lossy_ml"] {
        let cs_path = dir.join(format!("{stem}.j2c"));
        let ref_path = dir.join(format!("{stem}_ref.pgm"));
        if !cs_path.exists() || !ref_path.exists() {
            continue;
        }
        let img = jph_rs::mem::decode(&std::fs::read(&cs_path).unwrap());
        let expected = load_pgm(&ref_path);
        let got = &img.planes[0].samples;
        assert_eq!(got.len(), expected.len(), "{stem}: sample count");
        // Lossy, so compare to Kakadu's decode within a small peak-abs-error tolerance (different
        // implementations round the inverse 9/7 / dequant slightly differently). A broken
        // refinement decode produces gross corruption (PAE in the tens), so ±2 cleanly separates
        // correct from broken.
        let pae = got.iter().zip(&expected).map(|(a, b)| (a - b).abs()).max().unwrap_or(0);
        assert!(pae <= 2, "{stem}: peak abs error {pae} exceeds tolerance (refinement decode broken?)");
        checked += 1;
        println!("{stem}: PAE={pae} (SPP/MRP refinement OK)");
    }
    if checked == 0 {
        eprintln!("no spp_*.j2c fixtures found — skipping");
    }
}
